<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {Connection,DataLine,Grid,Loading,Monitor,Search,Select,Switch,VideoPause,VideoPlay,Warning} from '@element-plus/icons-vue';
import ZoneTrendChart from './ZoneTrendChart.vue';
import type {CropProfile,Device,Task} from '../../server/domain';

type PublicDevice=Device&{sampleCount:number};
type Locale='zh'|'uz';
type ViewMode='grid'|'topology'|'table';
type ZoneState='normal'|'dry'|'irrigating'|'offline';
const props=defineProps<{locale:Locale;devices:PublicDevice[];profiles:CropProfile[];tasks:Task[];busy:boolean}>();
const emit=defineEmits<{irrigate:[payload:{ids:string[];kind:'bulk'|'single'}];stop:[taskId:string]}>();
const query=ref(''),statusFilter=ref<'all'|ZoneState>('all'),controllerFilter=ref('all'),viewMode=ref<ViewMode>('grid'),selectedId=ref('B02'),selectedIds=ref<string[]>([]);
const text=computed(()=>props.locale==='zh'?{title:'分区监控',subtitle:'按控制器与分区查看传感器、阀门和闭环灌溉状态',all:'全部状态',normal:'正常',dry:'缺水',irrigating:'灌溉中',offline:'离线',search:'搜索分区或作物',selectDry:'选择全部缺水区',clear:'清除选择',batch:'灌溉所选分区',zones:'分区',online:'在线',warnings:'缺水',running:'灌溉中',offlineCount:'离线',live:'实时监测',crop:'作物档案',controller:'所属控制器',sensor:'传感器',valve:'电磁阀',target:'目标湿度',current:'当前湿度',temperature:'温度',light:'光照',trend:'土壤湿度趋势（近12小时）',start:'启动闭环灌溉',stop:'紧急停止',history:'最近操作记录',noHistory:'暂无灌溉记录',selected:'已选择',empty:'没有符合条件的分区'}:{title:'Hududlar nazorati',subtitle:'Kontroller, sensor, klapan va yopiq siklli sug‘orish holatini kuzating',all:'Barcha holatlar',normal:'Me’yorda',dry:'Suv yetishmaydi',irrigating:'Sug‘orilmoqda',offline:'Oflayn',search:'Hudud yoki ekinni qidiring',selectDry:'Barcha quruq hududlarni tanlash',clear:'Tanlovni tozalash',batch:'Tanlanganlarni sug‘orish',zones:'Hududlar',online:'Onlayn',warnings:'Quruq',running:'Sug‘orishda',offlineCount:'Oflayn',live:'Jonli nazorat',crop:'Ekin profili',controller:'Kontroller',sensor:'Sensor',valve:'Elektromagnit klapan',target:'Maqsad namlik',current:'Joriy namlik',temperature:'Harorat',light:'Yoritish',trend:'Tuproq namligi dinamikasi (12 soat)',start:'Yopiq siklli sug‘orish',stop:'Favqulodda to‘xtatish',history:'So‘nggi amallar',noHistory:'Sug‘orish yozuvlari yo‘q',selected:'Tanlandi',empty:'Mos hudud topilmadi'});
const profileFor=(device:PublicDevice)=>props.profiles.find(profile=>profile.id===device.cropId);
const activeResult=(id:string)=>{for(const task of props.tasks){if(task.type!=='water'||!['pending','running'].includes(task.status))continue;const result=task.results.find(item=>item.deviceId===id&&['pending','running'].includes(item.status));if(result)return {task,result};}};
const statusOf=(device:PublicDevice):ZoneState=>!device.online?'offline':activeResult(device.id)?'irrigating':device.moisture<(profileFor(device)?.moisture.targetMin??45)?'dry':'normal';
const statusEn=(status:ZoneState)=>({normal:'Normal',dry:'Dry',irrigating:'Irrigating',offline:'Offline'})[status];
const cropName=(device:PublicDevice)=>{const profile=profileFor(device);return props.locale==='zh'?(profile?.nameZh??device.name):(profile?.nameUz??device.nameEn);};
const cropImage=(device:PublicDevice)=>device.cropId==='tomato'?'/crop-tomato.png':['cucumber','pepper'].includes(device.cropId)?'/crop-pepper.png':['basil','coriander','green-onion'].includes(device.cropId)?'/crop-herbs.png':['lettuce','bok-choy','spinach','celery'].includes(device.cropId)?'/crop-lettuce.png':'/planter.png';
const counts=computed(()=>({online:props.devices.filter(item=>item.online).length,dry:props.devices.filter(item=>statusOf(item)==='dry').length,running:props.devices.filter(item=>statusOf(item)==='irrigating').length,offline:props.devices.filter(item=>statusOf(item)==='offline').length}));
const filtered=computed(()=>props.devices.filter(device=>{const term=query.value.trim().toLowerCase(),profile=profileFor(device);return (!term||[device.id,device.name,device.nameEn,profile?.nameZh,profile?.nameUz,profile?.nameEn].some(value=>value?.toLowerCase().includes(term)))&&(statusFilter.value==='all'||statusOf(device)===statusFilter.value)&&(controllerFilter.value==='all'||device.id[0]===controllerFilter.value);}));
const selected=computed(()=>props.devices.find(item=>item.id===selectedId.value)||props.devices[0]);
const selectedProfile=computed(()=>selected.value?profileFor(selected.value):undefined);
const selectedActive=computed(()=>selected.value?activeResult(selected.value.id):undefined);
const selectedLatest=computed(()=>{if(!selected.value)return;for(const task of props.tasks){const result=task.results.find(item=>item.deviceId===selected.value!.id);if(result)return {task,result};}});
const history=computed(()=>selected.value?props.tasks.filter(task=>task.results.some(result=>result.deviceId===selected.value!.id)).slice(0,5):[]);
const controllerGroups=computed(()=>['A','B','C','D'].map(id=>({id,devices:filtered.value.filter(device=>device.id.startsWith(id))})));
function toggle(id:string){selectedIds.value=selectedIds.value.includes(id)?selectedIds.value.filter(item=>item!==id):[...selectedIds.value,id];}
function selectDry(){selectedIds.value=filtered.value.filter(device=>statusOf(device)==='dry'&&device.online).map(device=>device.id);}
function startBulk(){const ids=selectedIds.value.filter(id=>{const device=props.devices.find(item=>item.id===id);return device&&statusOf(device)==='dry'&&device.online;});if(ids.length)emit('irrigate',{ids,kind:'bulk'});}
const stopLabel=(message:string)=>({TARGET_MOISTURE_REACHED:props.locale==='zh'?'达到目标湿度':'Maqsadga erishildi',MAX_VOLUME_REACHED:props.locale==='zh'?'达到最大水量':'Suv limiti',MAX_DURATION_REACHED:props.locale==='zh'?'达到最大时长':'Vaqt limiti',DEVICE_OFFLINE:props.locale==='zh'?'设备离线':'Qurilma oflayn',MANUAL_STOP:props.locale==='zh'?'手动停止':'Qo‘lda to‘xtatildi',SERVER_RESTART:props.locale==='zh'?'服务重启':'Server qayta ishga tushdi',RUNNING:props.locale==='zh'?'灌溉执行中':'Sug‘orilmoqda',PENDING:props.locale==='zh'?'等待执行':'Kutilmoqda'})[message]||message;
watch(()=>props.devices,devices=>{if(devices.length&&!devices.some(item=>item.id===selectedId.value))selectedId.value=devices[0].id;},{immediate:true});
</script>

<template><main class="zones-page"><header class="zones-header"><div><p class="eyebrow">ZONE OPERATIONS CENTER</p><h1>{{text.title}} <small>Zone Monitoring</small></h1><p>{{text.subtitle}}</p></div><div class="zone-summary"><article><strong>{{devices.length}}</strong><span><b>{{text.zones}}</b><small>Total Zones</small></span></article><article class="green"><strong>{{counts.online}}</strong><span><b>{{text.online}}</b><small>Online</small></span></article><article class="orange"><strong>{{counts.dry}}</strong><span><b>{{text.warnings}}</b><small>Water Required</small></span></article><article class="blue"><strong>{{counts.running}}</strong><span><b>{{text.running}}</b><small>Irrigating</small></span></article><article class="gray"><strong>{{counts.offline}}</strong><span><b>{{text.offlineCount}}</b><small>Offline</small></span></article></div></header>
 <section class="zone-toolbar"><label class="zone-search"><el-icon><Search/></el-icon><input v-model="query" :placeholder="`${text.search} / Search`"></label><select v-model="statusFilter"><option value="all">{{text.all}} / All</option><option value="normal">{{text.normal}} / Normal</option><option value="dry">{{text.dry}} / Dry</option><option value="irrigating">{{text.irrigating}} / Irrigating</option><option value="offline">{{text.offline}} / Offline</option></select><select v-model="controllerFilter"><option value="all">{{locale==='zh'?'全部控制器':'Barcha kontrollerlar'}} / All</option><option v-for="id in ['A','B','C','D']" :key="id" :value="id">{{id}}{{locale==='zh'?'区控制器':' hudud kontrolleri'}}</option></select><div class="view-switch"><button :class="{active:viewMode==='grid'}" @click="viewMode='grid'"><el-icon><Grid/></el-icon>Grid</button><button :class="{active:viewMode==='topology'}" @click="viewMode='topology'"><el-icon><Connection/></el-icon>Topology</button><button :class="{active:viewMode==='table'}" @click="viewMode='table'"><el-icon><DataLine/></el-icon>Table</button></div><button class="select-dry" @click="selectDry"><el-icon><Select/></el-icon>{{text.selectDry}}</button><button v-if="selectedIds.length" class="clear-selection" @click="selectedIds=[]">{{text.clear}}</button><button class="irrigate-selected" :disabled="!selectedIds.length||busy" @click="startBulk"><el-icon><Loading v-if="busy"/><VideoPlay v-else/></el-icon><span><b>{{text.batch}}</b><small>{{selectedIds.length}} {{text.selected}} · Irrigate Selected</small></span></button></section>
 <div class="zone-monitor-body"><section class="monitor-canvas"><div v-if="!filtered.length" class="zone-empty">{{text.empty}} / No matching zones</div><div v-else-if="viewMode==='grid'" class="monitor-grid"><article v-for="device in filtered" :key="device.id" :class="['monitor-zone-card',statusOf(device),{selected:selectedId===device.id,checked:selectedIds.includes(device.id)}]" @click="selectedId=device.id"><div class="monitor-card-head"><label @click.stop><input type="checkbox" :checked="selectedIds.includes(device.id)" :disabled="statusOf(device)==='offline'" @change="toggle(device.id)"><span></span></label><strong>{{device.id}}</strong><em><i></i>{{text[statusOf(device)]}}<small>{{statusEn(statusOf(device))}}</small></em></div><div class="monitor-crop"><img :src="cropImage(device)" :alt="cropName(device)"><p><b>{{cropName(device)}}</b><small>{{profileFor(device)?.nameEn}}</small></p><strong>{{device.online?`${device.moisture.toFixed(0)}%`:'--'}}</strong></div><div class="monitor-card-meta"><span>{{device.temperature}}°C<small>Temperature</small></span><span>{{device.light*800}} lux<small>Light</small></span><span><el-icon><Switch/></el-icon>{{activeResult(device.id)?(locale==='zh'?'开启':'Ochiq'):(locale==='zh'?'关闭':'Yopiq')}}<small>Valve</small></span></div><div v-if="activeResult(device.id)" class="card-progress"><i :style="{width:`${activeResult(device.id)!.result.progress}%`}"></i></div></article></div>
  <div v-else-if="viewMode==='topology'" class="topology-board"><div class="gateway-node"><el-icon><Monitor/></el-icon><b>{{locale==='zh'?'边缘网关':'Chekka shlyuz'}}</b><small>Edge Gateway · Online</small></div><div class="topology-trunk"></div><div class="controller-columns"><article v-for="group in controllerGroups" :key="group.id" class="controller-column"><header><span>{{group.id}}</span><p><b>{{group.id}}{{locale==='zh'?'区控制器':' hudud kontrolleri'}}</b><small>Zone {{group.id}} Controller</small></p><i></i></header><div class="controller-line"></div><button v-for="device in group.devices" :key="device.id" :class="['topology-zone',statusOf(device),{selected:selectedId===device.id}]" @click="selectedId=device.id"><i></i><span><b>{{device.id}} · {{cropName(device)}}</b><small>{{device.moisture.toFixed(0)}}% · {{statusEn(statusOf(device))}}</small></span><em>{{activeResult(device.id)?'ON':'OFF'}}</em></button></article></div></div>
  <div v-else class="zone-table-wrap"><table class="zone-table"><thead><tr><th></th><th>{{locale==='zh'?'分区':'Hudud'}}<small>Zone</small></th><th>{{locale==='zh'?'作物':'Ekin'}}<small>Crop</small></th><th>{{text.current}}<small>Moisture</small></th><th>{{text.target}}<small>Target</small></th><th>{{text.temperature}}<small>Temperature</small></th><th>{{text.sensor}}<small>Sensor</small></th><th>{{text.valve}}<small>Valve</small></th><th>{{locale==='zh'?'状态':'Holat'}}<small>Status</small></th></tr></thead><tbody><tr v-for="device in filtered" :key="device.id" :class="{selected:selectedId===device.id}" @click="selectedId=device.id"><td><input type="checkbox" :checked="selectedIds.includes(device.id)" @click.stop @change="toggle(device.id)"></td><td><b>{{device.id}}</b><small>{{device.id[0]}} Controller</small></td><td><b>{{cropName(device)}}</b><small>{{profileFor(device)?.nameEn}}</small></td><td><strong :class="statusOf(device)">{{device.moisture.toFixed(0)}}%</strong></td><td>{{profileFor(device)?.moisture.targetMin}}–{{profileFor(device)?.moisture.targetMax}}%</td><td>{{device.temperature}}°C</td><td>{{device.online?'Online':'Offline'}}</td><td>{{activeResult(device.id)?'OPEN':'CLOSED'}}</td><td><span :class="['table-status',statusOf(device)]"><i></i>{{text[statusOf(device)]}}</span></td></tr></tbody></table></div></section>
  <aside v-if="selected" class="zone-detail"><header><div><span>{{selected.id}}</span><p><b>{{cropName(selected)}}</b><small>{{selectedProfile?.nameEn}} · {{selected.id[0]}} Controller</small></p></div><em :class="statusOf(selected)"><i></i>{{text[statusOf(selected)]}}<small>{{statusEn(statusOf(selected))}}</small></em></header><section class="detail-device-strip"><span><el-icon><Connection/></el-icon><b>{{text.sensor}}</b><small>{{selected.online?'Online':'Offline'}}</small></span><span><el-icon><Switch/></el-icon><b>{{text.valve}}</b><small>{{selectedActive?'OPEN':'CLOSED'}}</small></span><span><el-icon><Monitor/></el-icon><b>{{text.controller}}</b><small>{{selected.id[0]}} Controller</small></span></section><section class="detail-readings"><article><small>{{text.current}} / Current</small><strong :class="statusOf(selected)">{{selected.moisture.toFixed(0)}}%</strong></article><article><small>{{text.target}} / Target</small><strong>{{selectedProfile?.moisture.targetMin}}–{{selectedProfile?.moisture.targetMax}}%</strong></article><article><small>{{text.temperature}} / Temperature</small><strong>{{selected.temperature}}°C</strong></article><article><small>{{text.light}} / Light</small><strong>{{selected.light*800}} lux</strong></article></section><section v-if="selectedLatest" :class="['zone-irrigation-progress',selectedLatest.result.status]"><div><span><el-icon :class="{'is-loading':Boolean(selectedActive)}"><Loading v-if="selectedActive"/><Warning v-else-if="selectedLatest.result.status==='failed'"/><Select v-else/></el-icon><b>{{stopLabel(selectedLatest.result.message)}}</b></span><strong>{{selectedLatest.result.progress}}%</strong></div><div class="progress-track"><i :style="{width:`${selectedLatest.result.progress}%`}"></i></div><p><span>{{selected.moisture.toFixed(0)}}% → {{selectedLatest.result.targetMoisture}}%<small>Current → Target</small></span><span>{{selectedLatest.result.delivered.toFixed(0)}} / {{selectedLatest.result.maxVolume}} mL<small>Delivered / Limit</small></span><span>{{selectedLatest.result.elapsedSeconds}}s<small>Elapsed</small></span></p></section><section class="detail-trend"><h2>{{text.trend}}</h2><p>Soil Moisture Trend · Database Samples</p><ZoneTrendChart :device="selected"/></section><div class="zone-control-buttons"><button v-if="selectedActive" class="stop-zone" :disabled="busy" @click="emit('stop',selectedActive.task.id)"><el-icon><VideoPause/></el-icon><span><b>{{text.stop}}</b><small>Emergency Stop</small></span></button><button v-else class="start-zone" :disabled="busy||statusOf(selected)!=='dry'" @click="emit('irrigate',{ids:[selected.id],kind:'single'})"><el-icon><VideoPlay/></el-icon><span><b>{{text.start}}</b><small>Start Closed-loop Irrigation</small></span></button></div><section class="zone-history"><h2>{{text.history}} <small>/ Operation Log</small></h2><div v-if="!history.length" class="no-history">{{text.noHistory}}</div><ul v-else><li v-for="task in history" :key="task.id"><i :class="task.status"></i><span><b>{{stopLabel(task.results.find(result=>result.deviceId===selected.id)?.message||task.status)}}</b><small>{{new Date(task.createdAt).toLocaleString(locale==='zh'?'zh-CN':'uz-UZ')}} · {{task.results.find(result=>result.deviceId===selected.id)?.delivered.toFixed(0)}} mL</small></span></li></ul></section></aside></div>
</main></template>
